-- Bai 01: Danh từ đếm được và không đếm được
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Danh từ đếm được và không đếm được', '<p data-n11="summary">Nhận diện danh từ đếm được, không đếm được và chọn lượng từ/phân chia động từ phù hợp.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Danh từ đếm được có dạng số ít và số nhiều (a report, reports). Danh từ không đếm được như information, equipment, advice, furniture thường không thêm -s và dùng động từ số ít khi làm chủ ngữ.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Danh từ đếm được số ít</td><td>a/an + singular countable noun</td></tr><tr><td>Danh từ đếm được số nhiều</td><td>many / several / a few + plural noun</td></tr><tr><td>Danh từ không đếm được</td><td>much / a little + uncountable noun</td></tr><tr><td>Đơn vị đếm</td><td>a piece of information / two pieces of equipment</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Much, little thường đi với danh từ không đếm được; many, few với danh từ đếm được. Some và a lot of dùng được cho cả hai.</p><h2>4. Lỗi thường gặp</h2><blockquote>Không viết informations hoặc equipments. Với một số từ như experience, nghĩa và tính đếm được thay đổi theo ngữ cảnh.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">We received useful information about the shipment.</p><p class="translation">Chúng tôi nhận được thông tin hữu ích về lô hàng.</p><p class="note">Information là không đếm được.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Several applicants attended the interview.</p><p class="translation">Một số ứng viên đã tham dự buổi phỏng vấn.</p><p class="note">Applicants là danh từ số nhiều đếm được.</p></article><article data-example-id="3" data-order="3"><p class="sentence">The company purchased three pieces of equipment.</p><p class="translation">Công ty đã mua ba thiết bị.</p><p class="note">Dùng pieces of để đếm equipment.</p></article></section>', 'BASIC', 31, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Danh từ đếm được và không đếm được');

-- Bai 02: Mạo từ a, an, the và không mạo từ
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Mạo từ a, an, the và không mạo từ', '<p data-n11="summary">Chọn mạo từ dựa trên tính xác định, âm đầu và cách dùng danh từ trong ngữ cảnh.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>A/an dùng cho danh từ đếm được số ít chưa xác định; an phụ thuộc âm đầu, không phụ thuộc chữ cái. The dùng khi người nghe đã xác định được đối tượng. Không dùng mạo từ với nhiều danh từ số nhiều/không đếm được mang nghĩa chung.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Chưa xác định</td><td>a report / an invoice</td></tr><tr><td>Đã xác định</td><td>the report you requested</td></tr><tr><td>Nhắc lại</td><td>I saw a file. The file was missing.</td></tr><tr><td>Nghĩa chung</td><td>Employees need training.</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Nhận diện danh từ số ít, âm đầu (an hour, a university), và các cụm xác định (the meeting scheduled for Monday).</p><h2>4. Lỗi thường gặp</h2><blockquote>Không chọn an chỉ vì từ bắt đầu bằng nguyên âm viết: university phát âm /juː/ nên dùng a.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Please send me an updated invoice.</p><p class="translation">Vui lòng gửi cho tôi một hóa đơn đã cập nhật.</p><p class="note">Updated bắt đầu bằng âm nguyên âm.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The report on your desk is confidential.</p><p class="translation">Báo cáo trên bàn bạn là tài liệu mật.</p><p class="note">Cụm on your desk xác định báo cáo cụ thể.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Training improves employee performance.</p><p class="translation">Đào tạo cải thiện hiệu suất nhân viên.</p><p class="note">Training mang nghĩa chung nên không có mạo từ.</p></article></section>', 'BASIC', 32, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Mạo từ a, an, the và không mạo từ');

-- Bai 03: Đại từ nhân xưng, sở hữu và phản thân
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Đại từ nhân xưng, sở hữu và phản thân', '<p data-n11="summary">Phân biệt chủ ngữ, tân ngữ, tính từ sở hữu, đại từ sở hữu và đại từ phản thân.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Chủ ngữ dùng I, you, he, she, it, we, they; tân ngữ dùng me, him, her, us, them. Tính từ sở hữu my/your/his/her/our/their phải đứng trước danh từ; đại từ sở hữu mine/yours/ours/theirs thay cho cả cụm danh từ. Phản thân dùng myself/yourself/himself... khi đối tượng trùng chủ thể.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Trước danh từ</td><td>their schedule / our office</td></tr><tr><td>Sau động từ hoặc giới từ</td><td>contact her / send it to them</td></tr><tr><td>Thay cụm danh từ sở hữu</td><td>The blue folder is mine.</td></tr><tr><td>Nhấn mạnh hoặc tự làm</td><td>The director herself signed the letter.</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Xem vị trí chỗ trống: trước một danh từ cần tính từ sở hữu; sau giới từ cần đại từ tân ngữ.</p><h2>4. Lỗi thường gặp</h2><blockquote>Its là sở hữu, it’s = it is/it has. Không dùng đại từ phản thân để thay thế chủ ngữ thông thường.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Please send the itinerary to her.</p><p class="translation">Vui lòng gửi lịch trình cho cô ấy.</p><p class="note">Sau giới từ to dùng tân ngữ her.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Their proposal was approved yesterday.</p><p class="translation">Đề xuất của họ đã được phê duyệt hôm qua.</p><p class="note">Their bổ nghĩa cho proposal.</p></article><article data-example-id="3" data-order="3"><p class="sentence">The manager prepared the presentation herself.</p><p class="translation">Quản lý tự chuẩn bị bài thuyết trình.</p><p class="note">Herself nhấn mạnh tự mình thực hiện.</p></article></section>', 'BASIC', 33, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Đại từ nhân xưng, sở hữu và phản thân');

-- Bai 04: Tính từ và trạng từ trong câu TOEIC
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Tính từ và trạng từ trong câu TOEIC', '<p data-n11="summary">Phân biệt tính từ bổ nghĩa danh từ và trạng từ bổ nghĩa động từ, tính từ hoặc cả câu.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Tính từ thường đứng trước danh từ hoặc sau liên động từ như be, seem, become. Trạng từ thường đứng gần động từ, tính từ hoặc trạng từ mà nó bổ nghĩa. Hầu hết trạng từ hình thành với -ly nhưng có ngoại lệ như fast, hard, late.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Trước danh từ</td><td>an accurate report</td></tr><tr><td>Sau động từ be/seem</td><td>The report is accurate.</td></tr><tr><td>Bổ nghĩa động từ</td><td>respond promptly</td></tr><tr><td>Bổ nghĩa tính từ</td><td>highly effective</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Các cặp cùng gốc: success/successful/successfully; accuracy/accurate/accurately.</p><h2>4. Lỗi thường gặp</h2><blockquote>Hard là chăm chỉ/mạnh, hardly là hầu như không. Friendly là tính từ dù có đuôi -ly.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The assistant handled the complaint professionally.</p><p class="translation">Trợ lý xử lý khiếu nại một cách chuyên nghiệp.</p><p class="note">Professionally bổ nghĩa cho handled.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The revised schedule is accurate.</p><p class="translation">Lịch đã sửa rất chính xác.</p><p class="note">Sau is là tính từ accurate.</p></article><article data-example-id="3" data-order="3"><p class="sentence">We need a reliable supplier.</p><p class="translation">Chúng ta cần một nhà cung cấp đáng tin cậy.</p><p class="note">Reliable bổ nghĩa cho supplier.</p></article></section>', 'BASIC', 34, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Tính từ và trạng từ trong câu TOEIC');

-- Bai 05: So sánh hơn, so sánh nhất và so sánh bằng
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'So sánh hơn, so sánh nhất và so sánh bằng', '<p data-n11="summary">Sử dụng đúng các dạng more/most, -er/-est và cấu trúc as ... as trong báo cáo công việc.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>So sánh hơn đối chiếu hai đối tượng bằng adjective-er hoặc more + adjective, thường theo sau là than. So sánh nhất dùng the + adjective-est/the most + adjective. So sánh bằng dùng as + adjective/adverb + as.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Tính từ ngắn</td><td>faster than / the fastest</td></tr><tr><td>Tính từ dài</td><td>more reliable than / the most reliable</td></tr><tr><td>Bằng nhau</td><td>as efficient as</td></tr><tr><td>So sánh số lượng</td><td>fewer complaints / less time</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Than là dấu hiệu so sánh hơn; among/of all thường gợi ý so sánh nhất. Less + danh từ không đếm được, fewer + danh từ đếm được.</p><h2>4. Lỗi thường gặp</h2><blockquote>Không dùng more faster hoặc most quickest. Farther/further có thể mang sắc thái khác nhau tùy ngữ cảnh.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">This route is faster than the highway route.</p><p class="translation">Tuyến đường này nhanh hơn tuyến đường qua cao tốc.</p><p class="note">Faster là so sánh hơn của fast.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Our newest printer is the most reliable model.</p><p class="translation">Máy in mới nhất của chúng tôi là mẫu đáng tin cậy nhất.</p><p class="note">Most + tính từ dài.</p></article><article data-example-id="3" data-order="3"><p class="sentence">The online class is as helpful as the workshop.</p><p class="translation">Lớp trực tuyến hữu ích như buổi hội thảo.</p><p class="note">As ... as diễn tả tương đương.</p></article></section>', 'INTERMEDIATE', 35, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='So sánh hơn, so sánh nhất và so sánh bằng');

-- Bai 06: Lượng từ: some, any, much, many, each, every
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Lượng từ: some, any, much, many, each, every', '<p data-n11="summary">Chọn từ chỉ lượng theo danh từ theo sau và cấu trúc động từ của cả câu.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Some thường xuất hiện trong câu khẳng định; any thường trong câu hỏi/phủ định (nhưng có ngoại lệ). Each/every đứng trước danh từ đếm được số ít và thường đi với động từ số ít. Many/few cho số nhiều đếm được; much/little cho không đếm được.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Danh từ số nhiều</td><td>many orders / a few clients</td></tr><tr><td>Không đếm được</td><td>much time / little information</td></tr><tr><td>Từng đối tượng</td><td>each employee / every branch</td></tr><tr><td>Một vài trong khẳng định</td><td>some documents</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Pay attention to each of + plural noun + singular verb (each of the reports is...).</p><h2>4. Lỗi thường gặp</h2><blockquote>Every employees là sai trong cách dùng thông thường; sau every phải là danh từ số ít.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Every employee receives an ID badge.</p><p class="translation">Mỗi nhân viên đều nhận thẻ nhân viên.</p><p class="note">Every đi với employee số ít.</p></article><article data-example-id="2" data-order="2"><p class="sentence">There is little time before the deadline.</p><p class="translation">Còn rất ít thời gian trước hạn chót.</p><p class="note">Time là không đếm được.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Some invoices are missing.</p><p class="translation">Một vài hóa đơn đang bị thiếu.</p><p class="note">Some đi với danh từ số nhiều.</p></article></section>', 'BASIC', 36, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Lượng từ: some, any, much, many, each, every');

-- Bai 07: Động từ khuyết thiếu: can, must, should, may
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Động từ khuyết thiếu: can, must, should, may', '<p data-n11="summary">Nắm cách diễn đạt khả năng, nghĩa vụ, lời khuyên và sự cho phép trong môi trường công việc.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Modal verbs như can, could, must, should, may, might đứng trước động từ nguyên mẫu không có to. Trong bị động, dùng modal + be + V3. Must not diễn tả cấm; do not have to diễn tả không bắt buộc.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Khả năng/cho phép</td><td>can + V / may + V</td></tr><tr><td>Nghĩa vụ</td><td>must + V / have to + V</td></tr><tr><td>Lời khuyên</td><td>should + V</td></tr><tr><td>Bị động</td><td>must be submitted / can be replaced</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Đọc ngữ nghĩa của quy định, yêu cầu và mức độ chắc chắn để chọn modal phù hợp.</p><h2>4. Lỗi thường gặp</h2><blockquote>Không dùng must to submit; sau modal phải là động từ nguyên mẫu. Mustn’t khác don’t have to.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Employees must wear safety helmets on site.</p><p class="translation">Nhân viên bắt buộc phải đội mũ bảo hộ tại công trường.</p><p class="note">Must biểu đạt nghĩa vụ.</p></article><article data-example-id="2" data-order="2"><p class="sentence">You should contact the supplier today.</p><p class="translation">Bạn nên liên hệ nhà cung cấp hôm nay.</p><p class="note">Should là lời khuyên.</p></article><article data-example-id="3" data-order="3"><p class="sentence">The form must be signed by the manager.</p><p class="translation">Biểu mẫu phải được quản lý ký.</p><p class="note">Modal + be + V3 ở dạng bị động.</p></article></section>', 'INTERMEDIATE', 37, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Động từ khuyết thiếu: can, must, should, may');

-- Bai 08: Danh động từ (V-ing) và động từ nguyên mẫu (to V)
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', '<p data-n11="summary">Nhận biết động từ theo sau bởi V-ing, to V hoặc động từ nguyên mẫu trong Part 5.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Một số động từ theo sau V-ing: enjoy, avoid, finish, consider, suggest. Một số khác theo sau to V: plan, decide, agree, hope, expect. Sau giới từ dùng V-ing; sau modal dùng V nguyên mẫu. Một số động từ có cả hai với khác biệt nghĩa (stop, remember).</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Sau giới từ</td><td>look forward to meeting</td></tr><tr><td>Sau decide/plan/hope</td><td>decide to postpone</td></tr><tr><td>Sau avoid/consider/enjoy</td><td>avoid making / consider hiring</td></tr><tr><td>Sau modal</td><td>should review</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Đừng nhầm to trong look forward to với to-V; to tại đây là giới từ nên đi với V-ing.</p><h2>4. Lỗi thường gặp</h2><blockquote>Suggest doing hoặc suggest that + S + V; tránh suggest to do trong cấu trúc thông dụng.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">We look forward to meeting your team.</p><p class="translation">Chúng tôi mong được gặp nhóm của bạn.</p><p class="note">To là giới từ sau look forward.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The manager decided to extend the deadline.</p><p class="translation">Quản lý quyết định gia hạn hạn chót.</p><p class="note">Decide + to V.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Please avoid opening suspicious attachments.</p><p class="translation">Hãy tránh mở các tệp đính kèm đáng ngờ.</p><p class="note">Avoid + V-ing.</p></article></section>', 'INTERMEDIATE', 38, 1, NULL
FROM grammar_topics t WHERE t.title='Từ loại'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Danh động từ (V-ing) và động từ nguyên mẫu (to V)');

-- Bai 09: Hòa hợp chủ ngữ và động từ
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Hòa hợp chủ ngữ và động từ', '<p data-n11="summary">Xác định chủ ngữ chính để chia động từ chính xác, kể cả khi có cụm từ chen giữa.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Danh từ trung tâm trong cụm chủ ngữ quyết định dạng số ít hay số nhiều của động từ. A list of documents là số ít vì list là danh từ trung tâm; the documents là số nhiều. Each/every thường yêu cầu động từ số ít. Either ... or / neither ... nor thường hòa hợp với danh từ gần động từ trong các mẫu điển hình.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Danh từ trung tâm</td><td>The list of guests is ready.</td></tr><tr><td>Each / Every</td><td>Each participant receives a badge.</td></tr><tr><td>Số nhiều</td><td>The documents are on the desk.</td></tr><tr><td>Chủ ngữ nối bằng and</td><td>Sales and marketing are cooperating.</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Đừng chia động từ theo danh từ đứng ngay cạnh nó nếu danh từ ấy chỉ thuộc cụm giới từ of, with hoặc along with.</p><h2>4. Lỗi thường gặp</h2><blockquote>The number of + danh từ số nhiều thường dùng động từ số ít; a number of + danh từ số nhiều thường dùng số nhiều.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The list of suppliers is on the intranet.</p><p class="translation">Danh sách nhà cung cấp nằm trên mạng nội bộ.</p><p class="note">List là chủ ngữ chính số ít.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Each member receives a security badge.</p><p class="translation">Mỗi thành viên nhận một thẻ an ninh.</p><p class="note">Each đi với động từ số ít.</p></article><article data-example-id="3" data-order="3"><p class="sentence">The reports from both offices are available.</p><p class="translation">Báo cáo từ hai văn phòng đã sẵn có.</p><p class="note">Reports là chủ ngữ số nhiều.</p></article></section>', 'BASIC', 39, 1, NULL
FROM grammar_topics t WHERE t.title='Cấu trúc câu'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Hòa hợp chủ ngữ và động từ');

-- Bai 10: Cấu trúc song song (Parallel Structure)
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Cấu trúc song song (Parallel Structure)', '<p data-n11="summary">Giữ các thành phần cùng chức năng ngữ pháp trong chuỗi liệt kê và cặp liên từ.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Trong danh sách nối bằng and/or, các thành phần thường phải đồng dạng: noun–noun, V-ing–V-ing, to V–to V. Các cặp both ... and, either ... or, not only ... but also cần thành phần song song. Điều này đặc biệt quan trọng khi TOEIC đưa các đáp án khác từ loại.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Danh động từ song song</td><td>planning, budgeting, and reporting</td></tr><tr><td>To-infinitive song song</td><td>to recruit and to train</td></tr><tr><td>Both ... and</td><td>both accurate and timely</td></tr><tr><td>Not only ... but also</td><td>not only efficient but also reliable</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Gạch chân các từ nối and/or/but also và so sánh dạng từ ngay trước/sau.</p><h2>4. Lỗi thường gặp</h2><blockquote>Trong thực tế đôi khi bỏ to ở động từ thứ hai (to plan and execute), vẫn là song song; không cần máy móc lặp to.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Our team handles planning, purchasing, and reporting.</p><p class="translation">Nhóm chúng tôi phụ trách lập kế hoạch, mua hàng và báo cáo.</p><p class="note">Ba danh động từ song song.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The process is both simple and efficient.</p><p class="translation">Quy trình vừa đơn giản vừa hiệu quả.</p><p class="note">Hai tính từ sau both ... and.</p></article><article data-example-id="3" data-order="3"><p class="sentence">She wants to review and revise the contract.</p><p class="translation">Cô ấy muốn xem xét và chỉnh sửa hợp đồng.</p><p class="note">Cả hai động từ cùng theo to.</p></article></section>', 'INTERMEDIATE', 40, 1, NULL
FROM grammar_topics t WHERE t.title='Cấu trúc câu'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Cấu trúc song song (Parallel Structure)');

-- Bai 11: Trật tự từ trong cụm danh từ TOEIC
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Trật tự từ trong cụm danh từ TOEIC', '<p data-n11="summary">Xác định vị trí tính từ, trạng từ, danh từ bổ nghĩa và danh từ trung tâm.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Một cụm danh từ trong TOEIC thường có: từ hạn định + trạng từ mức độ + tính từ + danh từ bổ nghĩa + danh từ trung tâm. Tính từ đứng trước danh từ, trạng từ đứng trước tính từ mà nó bổ nghĩa. Danh từ số ít có thể dùng để bổ nghĩa danh từ khác, như customer service.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Tính từ + danh từ</td><td>a detailed report</td></tr><tr><td>Trạng từ + tính từ</td><td>a highly effective strategy</td></tr><tr><td>Danh từ bổ nghĩa</td><td>customer satisfaction survey</td></tr><tr><td>Cụm danh từ</td><td>the revised annual budget proposal</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Nếu chỗ trống nằm trước tính từ, thường cần trạng từ; nếu trước danh từ trung tâm có thể cần tính từ hoặc danh từ bổ nghĩa.</p><h2>4. Lỗi thường gặp</h2><blockquote>Một số cụm cố định như human resources không theo mô hình đơn giản; ưu tiên collocation thông dụng.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The finance team prepared a detailed quarterly report.</p><p class="translation">Nhóm tài chính chuẩn bị báo cáo quý chi tiết.</p><p class="note">Detailed bổ nghĩa report.</p></article><article data-example-id="2" data-order="2"><p class="sentence">We launched a highly effective campaign.</p><p class="translation">Chúng tôi triển khai chiến dịch rất hiệu quả.</p><p class="note">Highly bổ nghĩa effective.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Customer feedback surveys help improve service.</p><p class="translation">Khảo sát phản hồi khách hàng giúp cải thiện dịch vụ.</p><p class="note">Customer và feedback bổ nghĩa surveys.</p></article></section>', 'INTERMEDIATE', 41, 1, NULL
FROM grammar_topics t WHERE t.title='Cấu trúc câu'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Trật tự từ trong cụm danh từ TOEIC');

-- Bai 12: Phân từ hiện tại và phân từ quá khứ
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Phân từ hiện tại và phân từ quá khứ', '<p data-n11="summary">Chọn V-ing/V3 để bổ nghĩa danh từ theo quan hệ chủ động hay bị động.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Phân từ V-ing thường diễn tả đối tượng tạo ra tác động hoặc đang thực hiện hành động (a growing business). V3/ed thường diễn tả đối tượng nhận tác động (a revised document). Các tính từ -ing/-ed còn mô tả nguyên nhân cảm xúc và trạng thái cảm xúc.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Chủ động</td><td>the employees attending the workshop</td></tr><tr><td>Bị động</td><td>the documents submitted yesterday</td></tr><tr><td>Tác nhân gây cảm xúc</td><td>an interesting seminar</td></tr><tr><td>Người có cảm xúc</td><td>interested participants</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Xác định danh từ trước phân từ đang làm hay nhận hành động; đừng chọn theo đuôi một cách máy móc.</p><h2>4. Lỗi thường gặp</h2><blockquote>The meeting was boring (gây chán), the attendees were bored (cảm thấy chán).</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The documents submitted yesterday are incomplete.</p><p class="translation">Tài liệu được nộp hôm qua chưa đầy đủ.</p><p class="note">Submitted bổ nghĩa documents ở nghĩa bị động.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The staff working on the project will meet at noon.</p><p class="translation">Nhân viên đang làm dự án sẽ họp lúc trưa.</p><p class="note">Working là quan hệ chủ động.</p></article><article data-example-id="3" data-order="3"><p class="sentence">The training session was interesting.</p><p class="translation">Buổi đào tạo rất thú vị.</p><p class="note">Interesting mô tả điều gây hứng thú.</p></article></section>', 'INTERMEDIATE', 42, 1, NULL
FROM grammar_topics t WHERE t.title='Cấu trúc câu'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Phân từ hiện tại và phân từ quá khứ');

-- Bai 13: Đảo ngữ với trạng từ phủ định và only
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Đảo ngữ với trạng từ phủ định và only', '<p data-n11="summary">Nhận diện cấu trúc đảo trợ động từ sau never, rarely, hardly, only after, not until.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Khi trạng từ/cụm trạng ngữ phủ định hoặc hạn định đứng đầu câu, trợ động từ thường được đưa lên trước chủ ngữ: Never have I seen..., Only after the review did we approve.... Nếu động từ chính không có trợ động từ, dùng do/does/did. Các cấu trúc này phổ biến ở văn phong trang trọng.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Never / Rarely</td><td>Never have we missed a deadline.</td></tr><tr><td>Not until</td><td>Not until Friday did we receive the parts.</td></tr><tr><td>Only after</td><td>Only after the audit did they release the funds.</td></tr><tr><td>Hardly ... when</td><td>Hardly had we arrived when the meeting began.</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Trong mệnh đề mở đầu Only after + noun/clause, phần đảo ngữ nằm ở mệnh đề chính, không nhất thiết ở mệnh đề sau after.</p><h2>4. Lỗi thường gặp</h2><blockquote>Đừng đảo ngữ trong câu bình thường nếu trạng từ không đứng đầu (We rarely receive...).</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Never have we experienced such delays.</p><p class="translation">Chưa bao giờ chúng tôi gặp tình trạng chậm trễ như thế.</p><p class="note">Never đầu câu đòi hỏi đảo trợ động từ have.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Only after approval can the work begin.</p><p class="translation">Chỉ sau khi được duyệt công việc mới có thể bắt đầu.</p><p class="note">Can đứng trước chủ ngữ.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Rarely does this machine require maintenance.</p><p class="translation">Máy này hiếm khi cần bảo trì.</p><p class="note">Dùng does + chủ ngữ + V nguyên mẫu.</p></article></section>', 'ADVANCED', 43, 1, NULL
FROM grammar_topics t WHERE t.title='Cấu trúc câu'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Đảo ngữ với trạng từ phủ định và only');

-- Bai 14: Mệnh đề danh từ: that, whether, if, what
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Mệnh đề danh từ: that, whether, if, what', '<p data-n11="summary">Dùng mệnh đề danh từ làm chủ ngữ, tân ngữ hoặc bổ ngữ; hiểu trật tự từ của câu hỏi gián tiếp.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Mệnh đề danh từ có thể bắt đầu bằng that, whether/if, what, who, when, where, why, how. Sau động từ như know, confirm, explain, mệnh đề phụ dùng trật tự khẳng định (không đảo trợ động từ như câu hỏi trực tiếp). Whether thường dùng được sau giới từ, hoặc trong cấu trúc whether ... or not.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Sau động từ tường thuật</td><td>We know that the report is ready.</td></tr><tr><td>Thông tin lựa chọn</td><td>Please confirm whether the shipment has arrived.</td></tr><tr><td>Từ nghi vấn</td><td>Tell us when the meeting starts.</td></tr><tr><td>Chủ ngữ trong mệnh đề</td><td>What she proposed was practical.</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Trong câu hỏi gián tiếp: Do you know where the manager is? (không viết where is the manager).</p><h2>4. Lỗi thường gặp</h2><blockquote>That không mang nghĩa nghi vấn; whether/if dùng khi không chắc điều gì có xảy ra.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Please confirm whether the invoice is correct.</p><p class="translation">Vui lòng xác nhận hóa đơn có đúng không.</p><p class="note">Whether mở mệnh đề có/không.</p></article><article data-example-id="2" data-order="2"><p class="sentence">We believe that the plan is feasible.</p><p class="translation">Chúng tôi tin rằng kế hoạch khả thi.</p><p class="note">That dẫn mệnh đề bổ nghĩa nội dung believe.</p></article><article data-example-id="3" data-order="3"><p class="sentence">I do not know when the package will arrive.</p><p class="translation">Tôi không biết khi nào kiện hàng đến.</p><p class="note">Mệnh đề gián tiếp giữ trật tự chủ ngữ + động từ.</p></article></section>', 'INTERMEDIATE', 44, 1, NULL
FROM grammar_topics t WHERE t.title='Mệnh đề'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Mệnh đề danh từ: that, whether, if, what');

-- Bai 15: Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', '<p data-n11="summary">Phân biệt when, while, because, although, unless trong câu phức TOEIC.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Mệnh đề trạng ngữ bổ sung thời gian, lý do, nhượng bộ hoặc điều kiện. Because + mệnh đề, because of + cụm danh từ. Although + mệnh đề, despite/in spite of + cụm danh từ hoặc V-ing. Unless = if ... not. Với thời gian tương lai sau when/after/before thường dùng hiện tại đơn thay cho will.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Nguyên nhân</td><td>because + S + V</td></tr><tr><td>Nhượng bộ</td><td>although + S + V</td></tr><tr><td>Thời gian</td><td>when/after/before + S + V</td></tr><tr><td>Điều kiện phủ định</td><td>unless + S + V</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Phân biệt because và because of qua thành phần đứng ngay sau chỗ trống.</p><h2>4. Lỗi thường gặp</h2><blockquote>Mệnh đề bắt đầu although không đi cùng but trong cùng cấu trúc chuẩn: Although..., ... .</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Although the shipment was delayed, the client remained calm.</p><p class="translation">Dù lô hàng bị trễ, khách hàng vẫn bình tĩnh.</p><p class="note">Although nối hai mệnh đề tương phản.</p></article><article data-example-id="2" data-order="2"><p class="sentence">We postponed the event because it was raining.</p><p class="translation">Chúng tôi hoãn sự kiện vì trời mưa.</p><p class="note">Because đi trước mệnh đề.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Please call me when the meeting ends.</p><p class="translation">Hãy gọi tôi khi cuộc họp kết thúc.</p><p class="note">Mệnh đề thời gian dùng hiện tại đơn cho tương lai.</p></article></section>', 'INTERMEDIATE', 45, 1, NULL
FROM grammar_topics t WHERE t.title='Mệnh đề'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ');

-- Bai 16: Rút gọn mệnh đề quan hệ
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Rút gọn mệnh đề quan hệ', '<p data-n11="summary">Chuyển mệnh đề who/which/that thành cụm phân từ phù hợp, phân biệt chủ động và bị động.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Khi mệnh đề quan hệ dùng who/which/that làm chủ ngữ, ta có thể rút gọn bằng V-ing nếu chủ động (employees working here), hoặc V3 nếu bị động (documents submitted yesterday). Một số mệnh đề có thể rút gọn bằng to-V trong ngữ cảnh thứ tự, mục đích hoặc cơ hội (the first person to arrive).</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Chủ động</td><td>people who attend → people attending</td></tr><tr><td>Bị động</td><td>reports that were prepared → reports prepared</td></tr><tr><td>Chỉ thứ tự</td><td>the first employee to arrive</td></tr><tr><td>Cụm giới từ</td><td>the files on the shelf</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Nhìn quan hệ giữa danh từ và hành động trước khi chọn -ing hoặc -ed; tránh rút gọn khi làm đổi nghĩa.</p><h2>4. Lỗi thường gặp</h2><blockquote>Không dùng participating cho documents được nộp; tài liệu không tự nộp chính nó.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The candidates selected for interviews will be contacted.</p><p class="translation">Các ứng viên được chọn phỏng vấn sẽ được liên hệ.</p><p class="note">Selected là bị động.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The employees attending the seminar must register.</p><p class="translation">Nhân viên tham dự hội thảo phải đăng ký.</p><p class="note">Attending là chủ động.</p></article><article data-example-id="3" data-order="3"><p class="sentence">She was the first person to submit the form.</p><p class="translation">Cô ấy là người đầu tiên nộp biểu mẫu.</p><p class="note">The first + to V.</p></article></section>', 'ADVANCED', 46, 1, NULL
FROM grammar_topics t WHERE t.title='Mệnh đề'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Rút gọn mệnh đề quan hệ');

-- Bai 17: Câu tường thuật và thay đổi thì
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Câu tường thuật và thay đổi thì', '<p data-n11="summary">Chuyển lời nói trực tiếp sang gián tiếp với said, told, asked và sự lùi thì phù hợp.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Khi động từ tường thuật ở quá khứ, trong nhiều trường hợp thì của câu trực tiếp lùi về quá khứ tương ứng (am/is → was, will → would, have/has V3 → had V3). Tell cần tân ngữ người nhận; say có thể không cần. Câu hỏi gián tiếp dùng trật tự S + V.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Lời kể</td><td>He said that he was busy.</td></tr><tr><td>Nói với ai</td><td>She told us that the meeting was canceled.</td></tr><tr><td>Câu hỏi yes/no</td><td>He asked if the invoice was ready.</td></tr><tr><td>Yêu cầu</td><td>The manager asked us to wait.</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Nếu sự thật vẫn còn đúng, đôi khi có thể giữ nguyên thì; không phải mọi câu gián tiếp đều bắt buộc lùi thì.</p><h2>4. Lỗi thường gặp</h2><blockquote>Said me thường không đúng; dùng told me hoặc said to me.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The manager told us that the schedule had changed.</p><p class="translation">Quản lý nói với chúng tôi rằng lịch đã thay đổi.</p><p class="note">Told cần người nghe us.</p></article><article data-example-id="2" data-order="2"><p class="sentence">She asked whether the contract was signed.</p><p class="translation">Cô ấy hỏi hợp đồng đã được ký chưa.</p><p class="note">Whether + mệnh đề khẳng định.</p></article><article data-example-id="3" data-order="3"><p class="sentence">He said he would call later.</p><p class="translation">Anh ấy nói anh ấy sẽ gọi sau.</p><p class="note">Will chuyển thành would khi lùi thì.</p></article></section>', 'INTERMEDIATE', 47, 1, NULL
FROM grammar_topics t WHERE t.title='Mệnh đề'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Câu tường thuật và thay đổi thì');

-- Bai 18: Giới từ chỉ thời gian và địa điểm
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Giới từ chỉ thời gian và địa điểm', '<p data-n11="summary">Sử dụng chính xác at/on/in/by/for/since trong email, lịch họp và thông báo TOEIC.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>At dùng cho giờ và địa điểm cụ thể; on cho ngày; in cho tháng, năm, mùa và không gian lớn hơn. By + mốc thời gian diễn tả chậm nhất trước hạn, until + mốc diễn tả kéo dài đến mốc. Since chỉ thời điểm bắt đầu; for chỉ khoảng thời gian.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Thời gian</td><td>at 9 a.m. / on Monday / in November</td></tr><tr><td>Hạn chót</td><td>by Friday</td></tr><tr><td>Kéo dài tới</td><td>until 6 p.m.</td></tr><tr><td>Khoảng thời gian</td><td>for three days / since 2023</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Đặc biệt phân biệt by Friday (trễ nhất thứ Sáu) và until Friday (kéo dài tới thứ Sáu).</p><h2>4. Lỗi thường gặp</h2><blockquote>Không dùng in Monday hoặc on 9 a.m. trong cách diễn đạt tiêu chuẩn.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The presentation starts at 2 p.m.</p><p class="translation">Bài thuyết trình bắt đầu lúc 2 giờ chiều.</p><p class="note">At dùng cho giờ.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Please submit the form by Friday.</p><p class="translation">Vui lòng nộp biểu mẫu chậm nhất thứ Sáu.</p><p class="note">By đánh dấu hạn cuối.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Our branch has operated here since 2020.</p><p class="translation">Chi nhánh chúng tôi hoạt động ở đây từ năm 2020.</p><p class="note">Since theo sau bởi mốc thời gian.</p></article></section>', 'BASIC', 48, 1, NULL
FROM grammar_topics t WHERE t.title='Giới từ và liên từ'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Giới từ chỉ thời gian và địa điểm');

-- Bai 19: Giới từ cố định sau động từ và tính từ
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Giới từ cố định sau động từ và tính từ', '<p data-n11="summary">Học các cụm phụ thuộc giới từ thường gặp: responsible for, interested in, depend on, comply with.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Nhiều động từ và tính từ đi với giới từ cố định tạo thành cụm nghĩa: responsible for, interested in, familiar with, depend on, participate in, comply with, apologize for. Trong Part 5, xác định cụm từ quen thuộc trước khi dịch từng từ.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Tính từ</td><td>responsible for / interested in / familiar with</td></tr><tr><td>Động từ</td><td>depend on / participate in / comply with</td></tr><tr><td>Cụm email</td><td>apologize for the delay</td></tr><tr><td>Bổ ngữ giới từ</td><td>look forward to the meeting</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Ghi nhớ cụm từ trọn vẹn cùng ví dụ trong bối cảnh công sở.</p><h2>4. Lỗi thường gặp</h2><blockquote>Different from thường an toàn trong văn phong kiểm tra; các biến thể khác có thể được chấp nhận tùy ngữ cảnh.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The department is responsible for payroll.</p><p class="translation">Phòng ban chịu trách nhiệm về bảng lương.</p><p class="note">Responsible for là cụm cố định.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Our project depends on supplier approval.</p><p class="translation">Dự án phụ thuộc vào việc nhà cung cấp phê duyệt.</p><p class="note">Depend on là cụm cố định.</p></article><article data-example-id="3" data-order="3"><p class="sentence">All staff must comply with company policy.</p><p class="translation">Tất cả nhân viên phải tuân thủ chính sách công ty.</p><p class="note">Comply with là cụm cố định.</p></article></section>', 'INTERMEDIATE', 49, 1, NULL
FROM grammar_topics t WHERE t.title='Giới từ và liên từ'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Giới từ cố định sau động từ và tính từ');

-- Bai 20: Phân biệt because/because of, although/despite và during/while
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published,created_by)
SELECT t.id, 'Phân biệt because/because of, although/despite và during/while', '<p data-n11="summary">Xác định sau chỗ trống là mệnh đề hay cụm danh từ để chọn từ nối chính xác.</p><section data-n11="lecture"><h2>1. Kiến thức cốt lõi</h2><p>Because + S + V, because of + noun phrase. Although/even though + S + V, despite/in spite of + noun phrase/V-ing. During + danh từ chỉ khoảng thời gian/sự kiện, while + mệnh đề. Đây là nhóm bẫy thường gặp khi làm TOEIC Part 5.</p><h2>2. Công thức và vị trí cần nhớ</h2><table><thead><tr><th>Trường hợp</th><th>Cấu trúc / Ví dụ</th></tr></thead><tbody><tr><td>Nguyên nhân</td><td>because the train was late / because of the delay</td></tr><tr><td>Nhượng bộ</td><td>although it rained / despite the rain</td></tr><tr><td>Thời gian</td><td>during the meeting / while we were meeting</td></tr><tr><td>Giới từ + V-ing</td><td>despite being tired</td></tr></tbody></table><h2>3. Dấu hiệu nhận biết và mẹo TOEIC</h2><p>Quan sát ngay sau chỗ trống có đủ chủ ngữ–động từ hay không; nếu có, ưu tiên liên từ thay vì giới từ.</p><h2>4. Lỗi thường gặp</h2><blockquote>Không viết despite of trong cấu trúc thông thường; dùng despite hoặc in spite of.</blockquote><p>Hãy xem tab Ví dụ rồi làm phần Luyện tập hoặc Thi để kiểm tra kiến thức.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">The flight was delayed because of bad weather.</p><p class="translation">Chuyến bay hoãn do thời tiết xấu.</p><p class="note">Because of + danh từ.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Although the office was crowded, everyone found a seat.</p><p class="translation">Dù văn phòng đông, mọi người đều có chỗ ngồi.</p><p class="note">Although + mệnh đề.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Please silence your phone during the meeting.</p><p class="translation">Vui lòng để điện thoại im lặng trong cuộc họp.</p><p class="note">During + danh từ meeting.</p></article></section>', 'INTERMEDIATE', 50, 1, NULL
FROM grammar_topics t WHERE t.title='Giới từ và liên từ'
AND NOT EXISTS (SELECT 1 FROM grammar_lessons old WHERE old.topic_id=t.id AND old.title='Phân biệt because/because of, although/despite và during/while');

DROP TEMPORARY TABLE IF EXISTS _n11_grammar_import;
CREATE TEMPORARY TABLE _n11_grammar_import (
  topic_title VARCHAR(180) NOT NULL,
  lesson_title VARCHAR(200) NOT NULL,
  question_text TEXT NOT NULL,
  explanation TEXT NOT NULL,
  difficulty TINYINT UNSIGNED NOT NULL,
  sort_order INT UNSIGNED NOT NULL,
  option_a TEXT NOT NULL, option_b TEXT NOT NULL,
  option_c TEXT NOT NULL, option_d TEXT NOT NULL,
  correct_label CHAR(1) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO _n11_grammar_import(topic_title,lesson_title,question_text,explanation,difficulty,sort_order,option_a,option_b,option_c,option_d,correct_label) VALUES
('Từ loại', 'Danh từ đếm được và không đếm được', 'The manager requested additional _____ before approving the proposal.', 'Information là danh từ không đếm được và phù hợp sau additional.', 1, 1, 'informations', 'information', 'informing', 'informative', 'B'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'We need _____ chairs for the conference room.', 'Chairs là danh từ số nhiều đếm được nên several là lựa chọn phù hợp.', 1, 2, 'much', 'a little', 'several', 'an', 'C'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'The new _____ is scheduled to arrive on Friday.', 'Equipment là danh từ không đếm được, dùng động từ is ở số ít.', 1, 3, 'equipment', 'equipments', 'equip', 'equipped', 'A'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'Only a _____ of the employees attended the optional workshop.', 'Employees là danh từ đếm được số nhiều nên a few là phù hợp.', 2, 4, 'little', 'few', 'much', 'piece', 'B'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'The technician gave us two useful _____ of advice.', 'Advice không đếm được nên dùng two pieces of advice.', 2, 5, 'units', 'pieces', 'advices', 'many', 'B'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'Ms. Park has _____ appointment with the director at 10 a.m.', 'Appointment bắt đầu bằng âm nguyên âm và được nhắc lần đầu.', 1, 1, 'a', 'an', 'the', 'no article', 'B'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'Please review _____ contract attached to this email.', 'Attached to this email xác định bản hợp đồng cụ thể.', 1, 2, 'a', 'an', 'the', 'no article', 'C'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'Our branch needs _____ new printer for the reception desk.', 'A new printer là danh từ đếm được số ít chưa xác định.', 1, 3, 'a', 'an', 'the', 'no article', 'A'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', '_____ employee training is important for workplace safety in general.', 'Employee training mang nghĩa khái quát, không cần mạo từ.', 2, 4, 'A', 'An', 'The', 'No article', 'D'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'The conference begins in _____ hour.', 'Hour có h câm nên bắt đầu bằng âm nguyên âm, dùng an.', 2, 5, 'a', 'an', 'the', 'no article', 'B'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'The marketing team will present _____ plan tomorrow.', 'Trước danh từ plan cần tính từ sở hữu their.', 1, 1, 'they', 'them', 'their', 'theirs', 'C'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'Please forward the confirmation email to _____.', 'Sau giới từ to cần đại từ tân ngữ her.', 1, 2, 'she', 'her', 'hers', 'herself', 'B'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'This workstation belongs to Alex; the other one is _____.', 'Mine là đại từ sở hữu đứng độc lập thay cho my workstation.', 2, 3, 'me', 'my', 'mine', 'myself', 'C'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'The CEO _____ welcomed the visiting clients.', 'Himself nhấn mạnh chính CEO đã đón tiếp khách hàng.', 2, 4, 'him', 'himself', 'his', 'he', 'B'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'The software automatically saves _____ settings.', 'Its bổ nghĩa cho settings; it’s là dạng rút gọn của it is.', 2, 5, 'it', 'its', 'itself', 'it’s', 'B'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The analyst completed the monthly report _____.', 'Completed là động từ nên cần trạng từ accurately.', 1, 1, 'accurate', 'accuracy', 'accurately', 'accuracies', 'C'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The company is looking for a _____ project coordinator.', 'Trước danh từ project coordinator cần tính từ reliable.', 1, 2, 'reliability', 'reliably', 'reliable', 'reliance', 'C'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The new ordering system is _____ efficient.', 'Highly là trạng từ bổ nghĩa cho tính từ efficient.', 2, 3, 'high', 'higher', 'height', 'highly', 'D'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The receptionist greeted the visitors _____.', 'Greeted cần trạng từ bổ nghĩa cách thức politely.', 1, 4, 'polite', 'politely', 'politeness', 'polites', 'B'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The annual review was _____ despite the tight deadline.', 'Sau liên động từ was dùng tính từ successful.', 2, 5, 'success', 'successful', 'successfully', 'succeed', 'B'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'This delivery service is _____ than the previous one.', 'Than yêu cầu dạng so sánh hơn, fast thành faster.', 1, 1, 'fast', 'faster', 'fastest', 'more faster', 'B'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'Of all the applicants, Ms. Green has _____ experience.', 'Of all gợi ý so sánh nhất; extensive dùng the most.', 2, 2, 'extensive', 'more extensive', 'the most extensive', 'as extensive', 'C'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'The updated software is as _____ as the old version.', 'Cấu trúc as + tính từ nguyên dạng + as.', 1, 3, 'stable', 'more stable', 'stablest', 'the most stable', 'A'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'We received _____ complaints this month than last month.', 'Complaints đếm được số nhiều, so sánh lượng dùng fewer.', 2, 4, 'less', 'fewer', 'little', 'the fewest', 'B'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'The new warehouse is much _____ from the city center than our old one.', 'Than yêu cầu so sánh hơn; farther phù hợp khoảng cách vật lý.', 2, 5, 'far', 'farthest', 'farther', 'most far', 'C'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', '_____ employee must wear an identification badge.', 'Every đi với danh từ đếm được số ít employee.', 1, 1, 'Every', 'Many', 'Few', 'Several', 'A'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'How _____ applications did the HR team receive?', 'Applications là danh từ số nhiều đếm được nên dùng many.', 1, 2, 'much', 'many', 'little', 'every', 'B'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'There is not _____ time left before the meeting.', 'Time là danh từ không đếm được nên dùng much.', 1, 3, 'many', 'a few', 'much', 'several', 'C'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'Each of the departments _____ responsible for its own budget.', 'Each of + danh từ số nhiều vẫn lấy each làm trung tâm số ít, dùng is.', 2, 4, 'are', 'be', 'is', 'were', 'C'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'We have _____ questions about the revised contract.', 'Questions là danh từ đếm được số nhiều và some phù hợp câu khẳng định.', 1, 5, 'some', 'much', 'every', 'little', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'All visitors _____ present a valid ID at reception.', 'Sau must là động từ nguyên mẫu present, không có to.', 1, 1, 'must', 'must to', 'musting', 'musted', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'The application _____ be submitted by Friday.', 'Bị động sau modal có dạng must be + V3.', 1, 2, 'must', 'must to', 'musting', 'musters', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'You _____ check the schedule before booking a meeting room.', 'Should + động từ nguyên mẫu để đưa ra lời khuyên.', 1, 3, 'should', 'should to', 'shoulding', 'shoulds', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'Employees _____ enter the laboratory without protective clothing.', 'Cấm vào phòng thí nghiệm nếu không có trang phục bảo hộ: must not.', 2, 4, 'must not', 'do not have to', 'may', 'can', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'If you have already registered, you _____ complete the form again.', 'Do not have to là không cần thiết, không phải cấm.', 2, 5, 'must not', 'do not have to', 'should', 'have to', 'B'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'We look forward to _____ from you soon.', 'Look forward to + V-ing, nên chọn hearing.', 1, 1, 'hear', 'hearing', 'heard', 'to hear', 'B'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'The board decided _____ the proposal until next week.', 'Decide + to V nên dùng to postpone.', 1, 2, 'postpone', 'postponing', 'to postpone', 'postponed', 'C'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'Employees should avoid _____ personal information online.', 'Avoid + V-ing nên dùng sharing.', 1, 3, 'share', 'to share', 'shared', 'sharing', 'D'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'Ms. Brown suggested _____ the training session online.', 'Suggest + V-ing để đề xuất một hoạt động.', 2, 4, 'hold', 'holding', 'to holding', 'held', 'B'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'The team agreed _____ the revised schedule.', 'Agree + to V biểu đạt đồng ý làm việc gì.', 2, 5, 'follow', 'following', 'to follow', 'followed', 'C'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'The list of approved vendors _____ updated monthly.', 'List là danh từ trung tâm số ít; vendors trong cụm of không quyết định động từ.', 1, 1, 'are', 'be', 'is', 'have', 'C'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'Every employee _____ access to the training portal.', 'Every employee là chủ ngữ số ít nên dùng has.', 1, 2, 'have', 'has', 'are', 'were', 'B'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'The reports on the manager’s desk _____ confidential.', 'Reports là danh từ trung tâm số nhiều nên dùng are.', 1, 3, 'is', 'was', 'has', 'are', 'D'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'A number of customers _____ requested refunds.', 'A number of + danh từ số nhiều thường dùng động từ số nhiều have.', 2, 4, 'has', 'have', 'is', 'was', 'B'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'The number of available rooms _____ decreasing.', 'The number of + danh từ số nhiều lấy number làm trung tâm số ít: is.', 2, 5, 'are', 'is', 'have', 'were', 'B'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The job requires writing reports, managing schedules, and _____ with clients.', 'Chuỗi writing, managing cần V-ing communicating.', 1, 1, 'communicate', 'communicated', 'communicating', 'to communicate', 'C'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The updated procedure is both practical and _____.', 'Both practical and reliable nối hai tính từ.', 1, 2, 'reliability', 'reliably', 'reliable', 'rely', 'C'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'Our goal is to reduce expenses and _____ service quality.', 'To reduce and improve là hai động từ nguyên mẫu song song.', 2, 3, 'improves', 'improved', 'improving', 'improve', 'D'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The training covers customer service, financial reporting, and _____.', 'Danh sách dùng các cụm danh từ/danh động từ, negotiating contracts phù hợp.', 2, 4, 'negotiating contracts', 'to negotiate contracts', 'negotiate contracts', 'negotiated contracts', 'A'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The proposal is not only affordable but also _____.', 'Affordable và innovative đều là tính từ trong cấu trúc song song.', 2, 5, 'innovation', 'innovative', 'innovatively', 'innovate', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The committee approved a _____ budget proposal.', 'Trước budget proposal cần tính từ revised.', 1, 1, 'revision', 'revised', 'revise', 'revisingly', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'We need a _____ detailed analysis of the results.', 'Trước tính từ detailed cần trạng từ particularly (đặc biệt chi tiết).', 2, 2, 'particular', 'particularly', 'particularity', 'particulars', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The company launched a new customer _____ program.', 'Cụm danh từ thông dụng là customer satisfaction program.', 2, 3, 'satisfy', 'satisfaction', 'satisfactory', 'satisfying', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The manager shared the _____ sales figures with the board.', 'Trước sales figures cần tính từ monthly.', 1, 4, 'month', 'monthly', 'months', 'monthlyness', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The team submitted a _____ prepared presentation.', 'Bổ nghĩa prepared bằng trạng từ professionally.', 2, 5, 'professional', 'profession', 'professionally', 'professionalism', 'C'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'The _____ contract must be signed by Friday.', 'Contract nhận hành động chỉnh sửa nên dùng revised.', 1, 1, 'revise', 'revising', 'revised', 'revision', 'C'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'Employees _____ in the safety workshop will receive certificates.', 'Employees chủ động tham gia, dùng V-ing participating.', 2, 2, 'participating', 'participated', 'participate', 'participation', 'A'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'The presentation was so _____ that everyone stayed until the end.', 'Presentation là tác nhân tạo hứng thú nên dùng interesting.', 1, 3, 'interest', 'interested', 'interesting', 'interests', 'C'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'The customers were _____ by the sudden schedule change.', 'Customers ở trạng thái bất ngờ nên dùng surprised.', 1, 4, 'surprising', 'surprised', 'surprise', 'surprises', 'B'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'Please archive all _____ invoices after payment.', 'Paid invoices là các hóa đơn đã được thanh toán.', 2, 5, 'pay', 'paying', 'paid', 'pays', 'C'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Never _____ the company received so many orders in one day.', 'Never đứng đầu câu yêu cầu đảo ngữ: has the company received.', 3, 1, 'has', 'have', 'had been', 'did has', 'A'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Rarely _____ this printer require maintenance.', 'Hiện tại đơn đảo ngữ với chủ ngữ this printer số ít cần does.', 3, 2, 'do', 'does', 'is', 'has', 'B'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Only after the inspection _____ the workers restart the machines.', 'Only after đặt đầu câu dẫn tới did + chủ ngữ + V nguyên mẫu.', 3, 3, 'was', 'did', 'has', 'are', 'B'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Not until yesterday _____ we receive the revised specifications.', 'Not until + quá khứ dẫn tới đảo ngữ did we receive.', 3, 4, 'do', 'have', 'did', 'are', 'C'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Hardly had the meeting started _____ the alarm went off.', 'Cặp cấu trúc cố định Hardly had ... when ... .', 3, 5, 'than', 'when', 'that', 'until', 'B'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'Could you tell me _____ the meeting starts?', 'When hỏi thời điểm bắt đầu cuộc họp và tạo mệnh đề danh từ.', 1, 1, 'when', 'what', 'that', 'which', 'A'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'The manager confirmed _____ all invoices had been paid.', 'That nối nội dung đã được xác nhận, không cần từ hỏi.', 2, 2, 'which', 'that', 'what', 'who', 'B'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'We need to determine _____ the supplier can deliver by Friday.', 'Whether diễn tả cần xác định có thể giao được hay không.', 2, 3, 'whether', 'whose', 'which', 'that time', 'A'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'Do you know where _____?', 'Câu hỏi gián tiếp dùng trật tự S + V: where the conference room is.', 2, 4, 'is the conference room', 'the conference room is', 'does the conference room', 'conference room being', 'B'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', '_____ the supervisor recommended was accepted by the team.', 'What đóng vai trò đối tượng được đề xuất và làm chủ ngữ cho was accepted.', 3, 5, 'That', 'What', 'Whether', 'If', 'B'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', '_____ the roads were flooded, the delivery arrived on time.', 'Although + mệnh đề the roads were flooded.', 1, 1, 'Despite', 'Although', 'Because of', 'During', 'B'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', 'We postponed the inspection _____ the heavy rain.', 'Because of theo sau bởi cụm danh từ the heavy rain.', 1, 2, 'because', 'although', 'because of', 'unless', 'C'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', 'Please wait here until the technician _____ the system.', 'Mệnh đề thời gian nói về tương lai dùng hiện tại đơn checks.', 2, 3, 'will check', 'checks', 'checking', 'to check', 'B'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', 'You will miss the deadline _____ you submit the report today.', 'Unless = if not, đúng nghĩa nếu không nộp hôm nay.', 2, 4, 'unless', 'although', 'because of', 'despite', 'A'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', '_____ the equipment was expensive, the company decided to purchase it.', 'Even though + mệnh đề chỉ nhượng bộ, phù hợp nghĩa đối lập.', 2, 5, 'Because of', 'In spite of', 'Even though', 'Despite', 'C'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The files _____ yesterday are now on the server.', 'Files nhận hành động upload, dùng V3 uploaded.', 2, 1, 'uploading', 'uploaded', 'uploads', 'to upload', 'B'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'Staff members _____ on the night shift receive an allowance.', 'Staff members chủ động làm ca đêm nên dùng working.', 2, 2, 'working', 'worked', 'works', 'to worked', 'A'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The first candidate _____ the interview received the offer.', 'Sau the first candidate dùng to V để chỉ người đầu tiên thực hiện.', 3, 3, 'complete', 'completing', 'to complete', 'completed', 'C'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The proposal _____ by the committee was accepted.', 'Proposal được ủy ban xem xét, dùng reviewed bị động.', 2, 4, 'reviewing', 'reviewed', 'reviews', 'to reviewing', 'B'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The people _____ in the lobby are here for the conference.', 'People đang chủ động chờ, dùng waiting.', 2, 5, 'waiting', 'waited', 'waits', 'be waiting', 'A'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'The supervisor _____ us that the meeting would start at nine.', 'Told cần tân ngữ người nhận us; said us là sai.', 1, 1, 'said', 'told', 'spoke', 'talked', 'B'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'She asked _____ the shipment had arrived.', 'Whether dẫn câu hỏi gián tiếp có/không.', 2, 2, 'that', 'whether', 'what', 'which', 'B'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'He said that he _____ the supplier the following day.', 'Will thường lùi thành would trong lời tường thuật quá khứ.', 2, 3, 'will call', 'would call', 'calls', 'has call', 'B'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'The manager asked the staff _____ quiet during the presentation.', 'Ask someone to V: asked the staff to remain.', 1, 4, 'remain', 'remaining', 'to remain', 'remained', 'C'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'They asked where the new branch _____.', 'Trong câu gián tiếp với asked quá khứ, was located là phù hợp.', 2, 5, 'is located', 'was located', 'located was', 'was locating', 'B'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'The monthly review will take place _____ Monday.', 'On đi với tên ngày trong tuần.', 1, 1, 'in', 'on', 'at', 'by', 'B'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'Please arrive _____ 8:30 a.m. for registration.', 'At đi với một giờ cụ thể.', 1, 2, 'in', 'on', 'at', 'during', 'C'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'All reimbursement claims must be submitted _____ Friday.', 'By Friday có nghĩa chậm nhất vào thứ Sáu.', 2, 3, 'until', 'since', 'by', 'for', 'C'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'She has worked at this branch _____ 2021.', 'Since theo sau mốc bắt đầu 2021.', 2, 4, 'for', 'since', 'during', 'by', 'B'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'The library will remain open _____ 9 p.m. tonight.', 'Remain open until 9 p.m. là trạng thái kéo dài tới 9 giờ.', 2, 5, 'until', 'by', 'since', 'for', 'A'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'Ms. Chen is responsible _____ preparing the quarterly budget.', 'Responsible for + V-ing/danh từ.', 1, 1, 'to', 'of', 'for', 'with', 'C'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'The success of the event depends _____ volunteer support.', 'Depend on là cụm cố định.', 1, 2, 'on', 'at', 'from', 'in', 'A'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'All employees must comply _____ the new security regulations.', 'Comply with regulations là cụm cố định.', 2, 3, 'to', 'with', 'for', 'about', 'B'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'The new interns are interested _____ attending the workshop.', 'Interested in + V-ing hoặc danh từ.', 1, 4, 'in', 'to', 'on', 'by', 'A'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'We apologize _____ the delay in processing your request.', 'Apologize for + danh từ.', 1, 5, 'on', 'with', 'at', 'for', 'D'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', 'The seminar was canceled _____ the speaker was ill.', 'Sau chỗ trống là mệnh đề the speaker was ill, nên dùng because.', 1, 1, 'because of', 'because', 'despite', 'during', 'B'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', '_____ the heavy traffic, the delivery truck arrived on time.', 'Despite theo sau cụm danh từ the heavy traffic, diễn tả tương phản.', 2, 2, 'Although', 'Because', 'Despite', 'While', 'C'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', 'Please keep your phone silent _____ the presentation.', 'During theo sau danh từ the presentation.', 1, 3, 'while', 'during', 'although', 'because', 'B'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', '_____ we were waiting for the manager, we reviewed the agenda.', 'While theo sau mệnh đề we were waiting.', 2, 4, 'During', 'Despite', 'While', 'Because of', 'C'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', 'The manager approved the purchase _____ the higher price.', 'Despite + noun phrase the higher price diễn tả nhượng bộ.', 2, 5, 'although', 'despite', 'while', 'because', 'B');

-- Chi them cau chua co, khong sua cau da co.
INSERT INTO grammar_questions(lesson_id, question_text, explanation, difficulty, sort_order)
SELECT l.id, s.question_text, s.explanation, s.difficulty, s.sort_order
FROM _n11_grammar_import s
JOIN grammar_topics t ON t.title=s.topic_title
JOIN grammar_lessons l ON l.topic_id=t.id AND l.title=s.lesson_title
WHERE NOT EXISTS (
  SELECT 1 FROM grammar_questions old
  WHERE old.lesson_id=l.id AND old.question_text=s.question_text
);

-- Moi cau co 4 lua chon A/B/C/D, dung 1 dap an dung.
INSERT INTO grammar_options(question_id,option_label,option_text,is_correct)
SELECT q.id, choice_labels.label,
  CASE choice_labels.label WHEN 'A' THEN s.option_a WHEN 'B' THEN s.option_b WHEN 'C' THEN s.option_c ELSE s.option_d END,
  (choice_labels.label = s.correct_label)
FROM _n11_grammar_import s
JOIN grammar_topics t ON t.title=s.topic_title
JOIN grammar_lessons l ON l.topic_id=t.id AND l.title=s.lesson_title
JOIN grammar_questions q ON q.lesson_id=l.id AND q.question_text=s.question_text
CROSS JOIN (SELECT 'A' AS label UNION ALL SELECT 'B' UNION ALL SELECT 'C' UNION ALL SELECT 'D') choice_labels
WHERE NOT EXISTS (SELECT 1 FROM grammar_options old WHERE old.question_id=q.id AND old.option_label=choice_labels.label);

DROP TEMPORARY TABLE IF EXISTS _n11_grammar_import;
COMMIT;

-- THONG KE SAU IMPORT (ket qua tong cong ca data cu):
SELECT (SELECT COUNT(*) FROM grammar_topics) AS total_topics,
       (SELECT COUNT(*) FROM grammar_lessons) AS total_lessons,
       (SELECT COUNT(*) FROM grammar_questions) AS total_questions,
       (SELECT COUNT(*) FROM grammar_options) AS total_options;
SELECT t.title AS topic, COUNT(DISTINCT l.id) AS lessons, COUNT(DISTINCT q.id) AS questions
FROM grammar_topics t LEFT JOIN grammar_lessons l ON l.topic_id=t.id
LEFT JOIN grammar_questions q ON q.lesson_id=l.id
GROUP BY t.id,t.title ORDER BY t.sort_order,t.id;
-- Kiem tra: Moi cau hoi thuong phai co 4 options va dung 1 correct.
SELECT q.id, q.question_text, COUNT(o.id) AS option_count,
       SUM(CASE WHEN o.is_correct=1 THEN 1 ELSE 0 END) AS correct_count
FROM grammar_questions q LEFT JOIN grammar_options o ON o.question_id=q.id
GROUP BY q.id,q.question_text
HAVING option_count<>4 OR correct_count<>1;
-- Ket qua rong la tot. Neu co dong nao, can kiem tra data cu truoc do.
